class Robot {
  name: string;
  model: string;

  constructor(name: string, model: string) {
    this.name = name;
    this.model = model;
  }
}

const ada = { name: 'Ada', email: 'ada@dlr.dev' };
const linus = { name: 'Linus' };
const robot = new Robot('R2', 'astromech');

for (const contact of [ada, linus, robot]) {
  console.log(label(contact));
}

quiz.prompt:
Cet appel compile-t-il ?
```ts
interface Contact { name: string; email?: string }
function label(c: Contact) { return c.name; }
label({ name: 'Ada', age: 36 });
```

Prédis la sortie :
```ts
interface Contact { name: string; email?: string }
const linus: Contact = { name: 'Linus' };
console.log(linus.email?.toUpperCase() ?? 'inconnu');
```

